<?php if(!$rows):?><p class="butchery-empty">Aucun document dans cette sélection.</p><?php else:?>
<div class="table-responsive"><table class="enterprise-table" <?=$filters?'data-butchery-history="documents"':''?> data-document-types="<?=e(json_encode($typeOptions,JSON_UNESCAPED_UNICODE))?>"><thead><tr><th>Numéro / type</th><th>Site</th><th>Date</th><th>Statut</th><th>Pièces</th><th>Créé par</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $d):?><tr data-status="<?=e($d['status'])?>" data-type="<?=e($d['document_type_id'])?>" data-date="<?=e(substr($d['document_date'],0,10))?>"><td><strong><?=e($d['document_number'])?></strong><small><?=e($d['display_code'].' · '.$d['type_name'])?></small></td><td><?=e($d['site_code'])?></td><td data-order="<?=e(strtotime($d['document_date']))?>"><?=e($date($d['document_date']))?></td><td><span class="butchery-status <?=in_array($d['status'],['approved','validated','closed'],true)?'butchery-status-success':''?>"><?=e($labels[$d['status']]??$d['status'])?></span></td><td data-order="<?=e($d['attachment_count'])?>"><?=e($d['attachment_count'])?></td><td><?=e($d['creator_name']?:'—')?></td><td><button class="btn-secondary" type="button" data-workspace-modal-open="document-detail-<?=e($d['id'])?>" aria-label="<?=e('Consulter '.$d['document_number'])?>">Détails</button></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
